{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "In fasting patients with advanced HIV infection, zalcitabine tablets had an absolute oral bioavailability of 80% (range 54-127%), directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "In healthy volunteers in the fasted state, a 100 mg immediate-release formulation had 34% bioavailability versus IV, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "In fasting patients, an oral solution with antacid had a bioavailability of 38% ± 15% versus IV, supporting F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All ten evidence molecules support high oral bioavailability; fasting-specific absolute values range from 34% to 80%, all above the 20% threshold, with no affirmative sub-20% fasting evidence.",
  "evidence_gaps": [
    "Some records are from non-fasted or unspecified conditions and were downweighted relative to fasting-specific records.",
    "A few records are qualitative or predicted rather than measured absolute bioavailability; they were not used as primary support."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

